const fs = require('node:fs')
const path = require('node:path')
const log = (line) => fs.appendFileSync(path.join(__dirname, 'calls.txt'), `${line}\n`)
module.exports = (tests) => {
  log(`filter got ${tests.length}: ${tests.map((t) => path.relative(__dirname, t)).sort().join(', ')}`)
  log(`absolute: ${tests.every((t) => path.isAbsolute(t))}`)
  return { filtered: tests.filter((t) => !t.endsWith('skipme.test.ts')) }
}
module.exports.setup = async () => {
  log('setup')
}
